"""
Propagate driven band dynamics and mixed variational responses through second order.

Consider a prescribed Cartesian periodic force $g_{\rm ext}(t,\lambda)$ in addition to the static molecular potential. It contributes $B^Tg_{\rm ext}$ to the modal residual force and no position Jacobian. This is a driven extension of the source's fixed-reference potential kicks. For one step from $t_n$ to $t_{n+1}$, use endpoint forcing in the symmetric composition

$$\Psi_n=\mathcal K_{h/2,t_{n+1}}\circ R_h\circ\mathcal K_{h/2,t_n}.$$

During a kick of duration $\tau$,

$$q^+=q,\qquad \pi^+=\pi+\tau[s(q,\lambda)+B^Tg_{\rm ext}],$$

and the tangent with respect to initial canonical coordinates changes by

$$J_q^+=J_q,\qquad J_\pi^+=J_\pi+\tau GJ_q.$$

The derivative layers of $y$ and $J$ are total derivatives along the parameter-dependent trajectory, with $J$ differentiating with respect to the local canonical initial state for each parameter. Consequently,

$$J_\pi^{[1]+}=J_\pi^{[1]}+\tau(G_1J_q^{[0]}+G_0J_q^{[1]}),$$

$$J_\pi^{[2]+}=J_\pi^{[2]}+\tau(G_2J_q^{[0]}+2G_1J_q^{[1]}+G_0J_q^{[2]}).$$

The position-response layers used in $G_1,G_2$ are those at the current kick. Between kicks, the moving harmonic map mixes derivative orders:

$$Y^{[2]+}=R_0Y^{[2]}+2R_1Y^{[1]}+R_2Y^{[0]},$$

for either the state vector or its tangent columns. The final kick uses the drifted geometry and the end-node forcing. Updating only the nominal trajectory or omitting the mixed propagator products gives incorrect second responses even when the nominal integration is accurate.

Returns
-------
np.ndarray, shape (3,2*k,1+2*k), driven state and tangent responses after one symmetric step.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def driven_band_jet_step(
    jet: "np.ndarray",
    eq: "np.ndarray",
    ref: "np.ndarray",
    R: "np.ndarray",
    A: "np.ndarray",
    C: "np.ndarray",
    cubic: "np.ndarray",
    beta: "np.ndarray",
    force: "np.ndarray",
    drive0: "np.ndarray",
    drive1: "np.ndarray",
    h: float,
) -> "np.ndarray":
    r"""Propagate driven band dynamics and mixed variational responses through second order.

    Parameters
    ----------
    jet : np.ndarray
        Shape (3,2*k,1+2*k). Column 0 holds y=(q,pi) and its total parameter
        responses; remaining columns hold J=dy/dy_initial and its total responses.
    eq, ref, R : np.ndarray
        Relaxed reference (3,s,s+1), anchored band (3,k+s,k), and harmonic
        propagator derivatives (3,2*k,2*k) for the specified signed h.
    A, C, cubic, beta, force : np.ndarray
        Potential arrays (3,s,s), (j,s), (j,), (3,j), (3,s), defined as above.
        Channel cubic and quartic terms have divisors 3 and 4, respectively.
    drive0, drive1 : np.ndarray
        Shape (3,s), Cartesian force derivatives at the starting and ending time nodes.
    h : float
        Signed timestep independent of lambda, consistent with R.

    Returns
    -------
    result, np.ndarray
        Same layout as jet after the residual half-kick, harmonic drift, and
        residual half-kick, including first/second parameter derivatives of both
        state and tangent. The reference changes with lambda but is fixed in time.

    All derivative arrays have leading axis (value, first derivative, second derivative) at lambda=0, with no factorial scaling. All data are real, finite, and conforming; inputs must be preserved.
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _kick_response(jet, eq, ref, A, C, cubic, beta, force, drive, tau):
    k = jet.shape[1] // 2
    response = _oracle_projected_force_response(
        eq, ref, A, C, cubic, beta, force, jet[:, :k, 0]
    )
    f = response[:, :, 0] + _jmat(_jtranspose(ref[:, k:]), drive)
    G = response[:, :, 1:]
    out = jet.copy()
    out[:, k:, 0] += tau * f
    out[:, k:, 1:] += tau * _jmat(G, jet[:, :k, 1:])
    return out


def _oracle_driven_band_jet_step(
    jet: "np.ndarray",
    eq: "np.ndarray",
    ref: "np.ndarray",
    R: "np.ndarray",
    A: "np.ndarray",
    C: "np.ndarray",
    cubic: "np.ndarray",
    beta: "np.ndarray",
    force: "np.ndarray",
    drive0: "np.ndarray",
    drive1: "np.ndarray",
    h: float,
) -> "np.ndarray":
    first = _kick_response(jet, eq, ref, A, C, cubic, beta, force, drive0, h / 2)
    middle = _jmat(R, first)
    result = _kick_response(middle, eq, ref, A, C, cubic, beta, force, drive1, h / 2)
    return result

